 const [selectedFixture,setSelectedFixture]=useState("");const [fixtures,setFixtures]=useState<Array<{id:string;competition:string;country:string;season:string;home_team:string;away_team:string;kickoff_at:string;status:string;home_score:number|null;away_score:number|null;live_minute:number|null;notes:string;match_court_id?:string|null;match_court_title?:string|null}>>([]);const [fixtureForm,setFixtureForm]=useState({competition:"",country:"",season:"2026/27",home_team:"",away_team:"",kickoff_at:"",status:"scheduled",notes:""});const [taskClaims,setTaskClaims]=useState<Array<{id:string;telegram_user_id:string;username?:string|null;first_name:string;task_key:string;title:string;reward_token:string;reward_amount:number;status:string;evidence?:string|null;review_note?:string|null;reviewed_by?:string|null;reviewed_at?:string|null;created_at:string}>>([]);
