 const [reviewNotes,setReviewNotes]=useState<Record<string,string>>({});const [auditEntries,setAuditEntries]=useState<Array<{id:string;action:string;target_type:string;target_id:string;details:string;created_at:string;administrator:string}>>([]);
 const fixtureTransitions=(status:string)=>({scheduled:["scheduled","live","postponed","cancelled"],live:["live","half_time","full_time","postponed","cancelled"],half_time:["half_time","live","full_time","postponed","cancelled"],full_time:["full_time"],postponed:["postponed","scheduled","cancelled"],cancelled:["cancelled"]} as Record<string,string[]>)[status]||[status];const loadFixtures=async()=>{try{const d=await api("/api/admin/fixtures");setFixtures(d.fixtures||[]);}catch(e){setError(e instanceof Error?e.message:"Fixtures could not be loaded.");}};const createFixture=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError("");try{await api("/api/admin/fixtures",{method:"POST",body:JSON.stringify(fixtureForm)});setNotice("Fixture created.");setFixtureForm(v=>({...v,home_team:"",away_team:"",kickoff_at:"",notes:""}));await loadFixtures();}catch(e){setError(e instanceof Error?e.message:"Fixture creation failed.");}finally{setBusy(false);}};const updateFixture=async(f:{id:string;status:string;home_score:number|null;away_score:number|null;live_minute:number|null})=>{setBusy(true);setError("");try{await api("/api/admin/fixtures/"+f.id,{method:"PATCH",body:JSON.stringify({status:f.status,home_score:f.home_score,away_score:f.away_score,live_minute:f.live_minute})});setNotice("Match status, score and minute saved.");await loadFixtures();}catch(e){setError(e instanceof Error?e.message:"Fixture update failed.");}finally{setBusy(false);}};
 const linkFixtureCourt=async(fixtureId:string,courtId:string)=>{if(!courtId){setError("Choose a Court to link.");return;}setBusy(true);setError("");try{await api("/api/admin/fixtures/"+encodeURIComponent(fixtureId)+"/link-court",{method:"POST",body:JSON.stringify({court_id:courtId})});setNotice("Fixture linked to its Match Court.");await loadFixtures();}catch(e){setError(e instanceof Error?e.message:"Fixture and Court could not be linked.");}finally{setBusy(false);}};const loadTaskClaims=async()=>{try{const d=await api("/api/admin/task-claims");setTaskClaims(d.claims||[]);}catch(e){setError(e instanceof Error?e.message:"Task claims could not be loaded.");}};
