 const reviewTaskClaim=async(id:string,decision:"approved"|"rejected")=>{setBusy(true);try{await api("/api/admin/task-claims/"+id+"/review",{method:"POST",body:JSON.stringify({decision,note:reviewNotes[id]||""})});setNotice("Task claim "+decision+".");await loadTaskClaims();await loadWalletAudit();await loadAuditEntries();}catch(e){setError(e instanceof Error?e.message:"Task claim review failed.");}finally{setBusy(false);}};
 const reviewReport=async(id:string,status:"reviewing"|"actioned"|"dismissed")=>{setBusy(true);try{await api("/api/admin/moderation/"+id+"/review",{method:"POST",body:JSON.stringify({status,note:reviewNotes[id]||""})});setNotice("Moderation report updated.");await loadReports();await loadAuditEntries();}catch(e){setError(e instanceof Error?e.message:"Moderation update failed.");}finally{setBusy(false);}};
 const moderateContent=async(reportId:string,action:"hidden"|"removed"|"visible")=>{setBusy(true);try{await api("/api/admin/moderation/"+reportId+"/content",{method:"POST",body:JSON.stringify({action})});setNotice("Reported content "+action+".");await loadReports();await loadAuditEntries();}catch(e){setError(e instanceof Error?e.message:"Content moderation failed.");}finally{setBusy(false);}};
 const updateRestriction=async(reportId:string,userId:string,status:"active"|"restricted"|"suspended")=>{const reason=reviewNotes["user:"+userId]||"";if(reason.trim().length<10){setError("Enter a restriction reason of at least 10 characters.");return;}setBusy(true);try{await api("/api/admin/users/"+userId+"/restriction",{method:"POST",body:JSON.stringify({status,reason,report_id:reportId})});setNotice("Member status updated and report actioned.");await loadReports();await loadAuditEntries();}catch(e){setError(e instanceof Error?e.message:"Member status could not be updated.");}finally{setBusy(false);}};
 const [grantTarget,setGrantTarget]=useState("");const [grantAmount,setGrantAmount]=useState("3500");const [grantReason,setGrantReason]=useState("");const [grantReference,setGrantReference]=useState("STG-"+Date.now().toString(36).toUpperCase());const [grantConfirmed,setGrantConfirmed]=useState(false);const [grantHistory,setGrantHistory]=useState<WalletGrant[]>([]);
 const [walletAudit,setWalletAudit]=useState<WalletAudit|null>(null);const [sources,setSources]=useState<Source[]>([]);const [reviews,setReviews]=useState<Array<Record<string,unknown>>>([]);
 const [scores,setScores]=useState<Scores>(emptyScores);const [decision,setDecision]=useState("changes_requested");const [notes,setNotes]=useState("");const [imageVerified,setImageVerified]=useState(false);
 const total=useMemo(()=>Object.values(scores).reduce((a,b)=>a+b,0),[scores]);
 const loadStatus=async()=>{try{const s=await api("/api/admin/status");setStatus(s);if(s.authenticated){await loadQueue();await loadFixtures();await loadAdminCourts();await loadAdminPools();await loadWalletAudit();await loadWalletGrants();await loadTaskClaims();await loadReports();await loadAuditEntries();}}catch(e){setError(e instanceof Error?e.message:"Admin portal is unavailable.");}};
 const loadQueue=async()=>{try{const d=await api("/api/editorial/queue");setItems(d.suggestions||[]);}catch(e){setError(e instanceof Error?e.message:"Editorial queue could not be loaded.");}};
 const loadAdminCourts=async()=>{try{const d=await api("/api/admin/courts");setCourtItems(d.courts||[]);}catch(e){setError(e instanceof Error?e.message:"Court resolution queue could not be loaded.");}};const loadAdminPools=async()=>{try{const d=await api("/api/admin/pools");setPoolItems(d.pools||[]);}catch(e){setError(e instanceof Error?e.message:"Pool resolution queue could not be loaded.");}};
 const loadWalletAudit=async()=>{try{const d=await api("/api/admin/wallet-audit");setWalletAudit(d);}catch(e){setError(e instanceof Error?e.message:"Wallet audit could not be loaded.");}};
 const loadWalletGrants=async()=>{try{const d=await api("/api/admin/wallet-grants");setGrantHistory(d.grants||[]);}catch(e){setError(e instanceof Error?e.message:"CT grant history could not be loaded.");}};
 const submitGrant=async(e:FormEvent)=>{e.preventDefault();setError("");setBusy(true);try{const d=await api("/api/admin/wallet-grants",{method:"POST",body:JSON.stringify({telegram_user_id:grantTarget,amount:Number(grantAmount),reason:grantReason,transaction_reference:grantReference})});setNotice("CT grant recorded · "+Number(d.grant.amount).toLocaleString()+" CT credited.");setGrantTarget("");setGrantAmount("3500");setGrantReason("");setGrantReference("STG-"+Date.now().toString(36).toUpperCase());setGrantConfirmed(false);await loadWalletGrants();await loadWalletAudit();}catch(e){setError(e instanceof Error?e.message:"CT grant could not be completed.");}finally{setBusy(false);}};
 useEffect(()=>{loadStatus();},[]);
 const submitAuth=async(e:FormEvent)=>{e.preventDefault();setError("");setBusy(true);try{if(status?.setupRequired&&password!==confirm)throw new Error("The passwords do not match.");const d=await api(status?.setupRequired?"/api/admin/setup":"/api/admin/login",{method:"POST",body:JSON.stringify({email,password,setup_secret:status?.setupRequired?setupSecret:undefined})});setStatus({setupRequired:false,setupAvailable:true,authenticated:true,email:d.email});setPassword("");setConfirm("");setSetupSecret("");setNotice(status?.setupRequired?"Your administrator account has been created. Registration is now closed.":"Signed in successfully.");await loadQueue();await loadFixtures();await loadAdminCourts();await loadAdminPools();await loadWalletAudit();await loadWalletGrants();await loadTaskClaims();await loadReports();await loadAuditEntries();}catch(e){setError(e instanceof Error?e.message:"Authentication failed.");}finally{setBusy(false);}};
 const openSuggestion=async(item:Suggestion)=>{setError("");try{const d=await api("/api/editorial/suggestions/"+encodeURIComponent(item.id));setSelected(d.suggestion);setSelectedFixture(d.suggestion.fixture_id||"");setSources(d.sources||[]);setReviews(d.reviews||[]);setImageVerified(d.suggestion.image_review_status==="verified");const last=d.reviews?.[0];if(last){setScores({trending_score:Number(last.trending_score),disagreement_score:Number(last.disagreement_score),evidence_score:Number(last.evidence_score),clarity_score:Number(last.clarity_score),timeliness_score:Number(last.timeliness_score)});setDecision(String(last.decision));setNotes(String(last.notes||""));}else{setScores(emptyScores);setDecision("changes_requested");setNotes("");}}catch(e){setError(e instanceof Error?e.message:"Could not open suggestion.");}};
 const saveReview=async()=>{if(!selected)return;setBusy(true);setError("");try{const d=await api("/api/editorial/suggestions/"+encodeURIComponent(selected.id)+"/review",{method:"POST",body:JSON.stringify({...scores,decision,notes,image_relevance_verified:imageVerified})});setNotice("Review saved · "+d.total_score+"/100.");await loadQueue();await openSuggestion({...selected,status:decision});}catch(e){setError(e instanceof Error?e.message:"Review could not be saved.");}finally{setBusy(false);}};
 const linkSelectedFixture=async()=>{if(!selected)return;setBusy(true);setError("");try{await api("/api/editorial/suggestions/"+encodeURIComponent(selected.id)+"/fixture",{method:"POST",body:JSON.stringify({fixture_id:selectedFixture||null})});setSelected(v=>v?{...v,fixture_id:selectedFixture||null}:v);setNotice(selectedFixture?"Fixture linked to editorial submission.":"Fixture link removed.");}catch(e){setError(e instanceof Error?e.message:"Fixture could not be linked.");}finally{setBusy(false);}};const publish=async()=>{if(!selected)return;setBusy(true);setError("");try{await api("/api/editorial/suggestions/"+encodeURIComponent(selected.id)+"/publish",{method:"POST",body:"{}"});setNotice("Court published successfully.");setSelected(null);await loadQueue();}catch(e){setError(e instanceof Error?e.message:"Publication failed.");}finally{setBusy(false);}};
 const lockCourt=async(c:AdminCourt)=>{setBusy(true);setError("");try{await api("/api/admin/courts/"+encodeURIComponent(c.id)+"/lock",{method:"POST",body:"{}"});setNotice("Court locked. Arguments and reactions are now closed.");setActiveCourt({...c,status:"locked"});await loadAdminCourts();}catch(e){setError(e instanceof Error?e.message:"Court could not be locked.");}finally{setBusy(false);}};
